import{_ as t,o,c as a,a2 as i}from"./chunks/framework.Wk4ah3nE.js";const u=JSON.parse('{"title":"Reporting a vulnerability","description":"How to responsibly disclose a security vulnerability in Proxmox VM Autoscale, what to include, and what response to expect.","frontmatter":{"title":"Reporting a vulnerability","description":"How to responsibly disclose a security vulnerability in Proxmox VM Autoscale, what to include, and what response to expect.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/security/disclosure.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/security/disclosure.html"}],["meta",{"property":"og:title","content":"Reporting a vulnerability"}],["meta",{"property":"og:description","content":"How to responsibly disclose a security vulnerability in Proxmox VM Autoscale, what to include, and what response to expect."}]]},"headers":[],"relativePath":"security/disclosure.md","filePath":"security/disclosure.md","lastUpdated":null}'),r={name:"security/disclosure.md"};function s(l,e,n,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to &quot;Reporting a vulnerability&quot;">​</a></h1><h2 id="do-not-open-a-public-issue" tabindex="-1">Do not open a public issue <a class="header-anchor" href="#do-not-open-a-public-issue" aria-label="Permalink to &quot;Do not open a public issue&quot;">​</a></h2><p>Report privately by email:</p><p><strong><a href="mailto:fabrizio.salmi@gmail.com" target="_blank" rel="noreferrer">fabrizio.salmi@gmail.com</a></strong></p><p>Public disclosure before a fix exists puts every deployment at risk — and these deployments hold root credentials for hypervisors.</p><h2 id="what-to-include" tabindex="-1">What to include <a class="header-anchor" href="#what-to-include" aria-label="Permalink to &quot;What to include&quot;">​</a></h2><ul><li><strong>What it is</strong> — the class of issue and the component affected</li><li><strong>How to reproduce</strong> — steps, a proof of concept, or the code path</li><li><strong>Impact</strong> — what an attacker gains, and from what starting position</li><li><strong>Version</strong> — release tag or commit hash</li><li><strong>Suggested fix</strong>, if you have one</li><li><strong>How you would like to be credited</strong>, or that you prefer to stay anonymous</li></ul><h2 id="what-to-expect" tabindex="-1">What to expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to &quot;What to expect&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Timeline</th></tr></thead><tbody><tr><td>Acknowledgement</td><td>Within 48 hours</td></tr><tr><td>Initial assessment and a plan</td><td>Within 7 days</td></tr><tr><td>Fix</td><td>Depends on severity and complexity</td></tr><tr><td>Advisory and release</td><td>Together with the fix</td></tr></tbody></table><p>You will be kept informed as the fix progresses, credited in the advisory unless you prefer otherwise, and told when it is safe to publish.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p><strong>In scope</strong> — anything in this repository: the Python modules, <code>install.sh</code>, the systemd unit, the shipped configuration and the documentation where it recommends something unsafe.</p><p><strong>Out of scope</strong></p><ul><li>Vulnerabilities in Proxmox VE itself → <a href="https://pve.proxmox.com/wiki/Security" target="_blank" rel="noreferrer">Proxmox security</a></li><li>Vulnerabilities in <code>paramiko</code>, <code>PyYAML</code> or <code>requests</code> → report upstream, though do tell us if this project&#39;s usage makes one exploitable</li><li>Issues requiring root on the autoscaler host — root there is <a href="/proxmox-vm-autoscale/security/#root-on-the-autoscaler-host">already total compromise</a> by design</li><li>Weaknesses already documented on the <a href="/proxmox-vm-autoscale/reference/limitations.html">known limitations</a> page — they are known; a <em>new</em> exploitation path for one of them is very much in scope</li></ul><h2 id="already-known-weaknesses" tabindex="-1">Already-known weaknesses <a class="header-anchor" href="#already-known-weaknesses" aria-label="Permalink to &quot;Already-known weaknesses&quot;">​</a></h2><p>Please check these before reporting, so your effort goes somewhere useful:</p><ul><li>SSH host keys are auto-accepted with no pinning</li><li>Credentials are stored in plain text in <code>config.yaml</code></li><li>The service requires and runs as root</li><li><code>install.sh</code> is fetched over HTTPS and executed unverified</li><li>VMIDs are interpolated into shell command strings without validation</li></ul><p>All are documented in the <a href="/proxmox-vm-autoscale/security/">threat model</a>.</p><h2 id="supported-versions" tabindex="-1">Supported versions <a class="header-anchor" href="#supported-versions" aria-label="Permalink to &quot;Supported versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Supported</th></tr></thead><tbody><tr><td><code>main</code></td><td>✅</td></tr><tr><td>Latest release (<code>v0.1.1</code>)</td><td>✅</td></tr><tr><td>Older tags</td><td>⚠️ Alpha — upgrade</td></tr></tbody></table><p>Note that release tags are not in chronological order: <code>v1.2.0</code> predates <code>v0.1.1</code>.</p><h2 id="machine-readable" tabindex="-1">machine-readable <a class="header-anchor" href="#machine-readable" aria-label="Permalink to &quot;machine-readable&quot;">​</a></h2><p>A <a href="/proxmox-vm-autoscale/proxmox-vm-autoscale/.well-known/security.txt"><code>security.txt</code></a> is published under this site, per <a href="https://www.rfc-editor.org/rfc/rfc9116" target="_blank" rel="noreferrer">RFC 9116</a>.</p><div class="info custom-block"><p class="custom-block-title">About its location</p><p>RFC 9116 places <code>security.txt</code> at the root of a domain. This site lives under a path on <code>github.io</code>, so the file is served from the project path rather than the canonical one. It is provided for completeness; the email address above is the authoritative contact.</p></div><h2 id="security-updates" tabindex="-1">Security updates <a class="header-anchor" href="#security-updates" aria-label="Permalink to &quot;Security updates&quot;">​</a></h2><p>When an issue is fixed:</p><ol><li>It is developed and tested privately.</li><li>A GitHub security advisory is published.</li><li>A release is tagged with the fix.</li><li>Release notes describe the issue and the required action.</li></ol><p><a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale" target="_blank" rel="noreferrer">Watch the repository</a> → Custom → Releases to be notified.</p>',28)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
